export const WORDMARK_RATIO = 5.8097;

export function Wordmark({ className, title = "STRONG" }: { className?: string; title?: string }) {
  return (
    <svg className={className} viewBox="0 -0.70 589.10 101.40" fill="currentColor" {...(title ? { role: "img", "aria-label": title } : { "aria-hidden": true })}>
      <path fillRule="evenodd" d={D} />
    </svg>
  );
}

/** Wordmark + «UKRAINIAN BRAND», as in the logo file. */
export function Lockup({ className }: { className?: string }) {
  return (
    <span className={`lockup ${className ?? ""}`}>
      <Wordmark className="lockup-word" title="" />
      <span className="lockup-sub">Ukrainian brand</span>
    </span>
  );
}
